import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o,a as i,b as a}from"./chunks/M-S-SY3.DDtr6WYL.js";import{_ as s,o as n,c as r,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const w=JSON.parse('{"title":"Copy settings","description":"","frontmatter":{},"headers":[],"relativePath":"use/copysettings.md","filePath":"use/copysettings.md"}'),d={name:"use/copysettings.md"};function l(c,e,m,u,g,h){return n(),r("div",null,[...e[0]||(e[0]=[p('<p>xDrip provides an easy way to copy settings from one phone to another.</p><h3 id="show-settings-qr-code" tabindex="-1">Show Settings QR Code <a class="header-anchor" href="#show-settings-qr-code" aria-label="Permalink to &quot;Show Settings QR Code&quot;">​</a></h3><p>Show settings QR code displays a QR code containing xDrip settings.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"> Show Settings QR codes</p></div><div class="admonition xdrip"><p class="admonition-title">Share Settings via QR code</p><p> Use QR codes to transfer settings using Settings-&gt;Auto Configure feature</p></div><p>xDrip security key is used for xDrip Sync, if you only want to share a follower code (that is difficult to copy manually) use this.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  SECURITY KEY SETTINGS ONLY </div></p></div><p>If you used customization QR codes for this phone&#39;s xDrip (G7, 1+, BlueJay, ...), you can transfer them directly to another phone.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  EXPORT KEKS KEY TO ANOTHER PHONE </div></p></div><p>General and collection settings include general settings and your hardware data source settings.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  SHOW GENERAL AND COLLECTION SETTINGS </div></p></div><p>All settings include all (except alarms: you need to recreate them manually).</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  COPY ALL SETTINGS </div></p></div><p>You will obtain a QR code that you can scan with Auto Configure on another phone.</p><img src="'+o+'" style="zoom:75%;"><h3 id="auto-configure" tabindex="-1">Auto configure <a class="header-anchor" href="#auto-configure" aria-label="Permalink to &quot;Auto configure&quot;">​</a></h3><p>Auto configure allows you to import settings from a QR code.</p><p>Make sure the origin of the QR code you will scan is safe.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Auto configure</p></div><h4 id="camera" tabindex="-1">Camera <a class="header-anchor" href="#camera" aria-label="Permalink to &quot;Camera&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title">Camera</p><p> Scan a QR code with your mobile (recommended)</p></div><p>You need to authorize xDrip to access the phone camera.</p><p>You can then scan the QR code displayed on another phone in order to copy the settings you selected when displaying it as explained <a href="#show-settings-qr-code">above</a>.</p><img src="'+i+'" style="zoom:75%;"><p>Current settings will be overwritten, a list will be displayed for you to acknowledge.</p><div class="admonition xdripitem"><p class="admonition-title">Are you sure?</p><p> Only import settings from sources you trust!<br>  Please confirm to import the following settings:</p><p> setting1<br>  setting2<br>  setting3</p><p> No     Yes</p></div><p>A <em>Copy all settings</em> QR code doesn&#39;t contain the settings themselves: xDrip downloads them once you confirm. Since release 2026.11.21 you are asked to confirm first.</p><div class="admonition xdripitem"><p class="admonition-title">Are you sure?</p><p> Only import settings from sources you trust!<br>  Please confirm to download and import all settings from this code.</p></div><p>You might need to restart your phone to apply the changes.</p><h4 id="image-file" tabindex="-1">Image file <a class="header-anchor" href="#image-file" aria-label="Permalink to &quot;Image file&quot;">​</a></h4><p>If your phone has a bad quality video camera or none at all, you can load the QR code from a file.</p><p>You first need to save the QR code image you need to scan in your own pictures.</p><div class="admonition xdripitem"><p class="admonition-title">Image file</p><p> You can save a QR code as an image file (such as .png or .jpeg) on your mobile. Then, use this option to scan the QR code from the saved file.</p></div><p>Select the image containing the QR code.</p><img src="'+a+'" style="zoom:75%;"><p>Current settings will be overwritten, a list will be displayed for you to acknowledge.</p><div class="admonition xdripitem"><p class="admonition-title">Are you sure?</p><p> Only import settings from sources you trust!<br>  Please confirm to import the following settings:</p><p> setting1<br>  setting2<br>  setting3</p><p> No     Yes</p></div><p>You might need to restart your phone to apply the changes.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',40)])])}const x=s(d,[["render",l]]);export{w as __pageData,x as default};
